import{G as e,b as o,c as t,ae as r}from"./chunks/framework.l_MR1ur9.js";const _=JSON.parse('{"title":"入门","description":"","frontmatter":{"title":"入门","date":"2024/04/16 23:17:35","author":"花木凋零成兰","tags":[],"categories":["后端开发","Zookeeper"]},"headers":[],"relativePath":"Backend/Zookeeper/1.入门.md","filePath":"Backend/Zookeeper/1.入门.md","lastUpdated":1791630580000}'),i={name:"Backend/Zookeeper/1.入门.md"};function l(d,a,n,h,s,c){return o(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1713309455000"},[...a[0]||(a[0]=[r('<h1 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to &quot;入门&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Zookeeper是一个开源的分布式的,为分布式框架提供协调服务的Apache项目.</p><h3 id="工作机制" tabindex="-1">工作机制 <a class="header-anchor" href="#工作机制" aria-label="Permalink to &quot;工作机制&quot;">​</a></h3><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h3><p><strong>提供的服务:</strong></p><h4 id="统一命名服务" tabindex="-1">统一命名服务 <a class="header-anchor" href="#统一命名服务" aria-label="Permalink to &quot;统一命名服务&quot;">​</a></h4><p>在分布式环境下,经常需要对应用/服务进行统一命名,便于识别</p><p>例如: IP不容易记住, 而域名容易记住</p><h4 id="统一配置管理" tabindex="-1">统一配置管理 <a class="header-anchor" href="#统一配置管理" aria-label="Permalink to &quot;统一配置管理&quot;">​</a></h4><ol><li>在分布式环境下,配置文件同步非常常见 <ol><li>一边要求一个集群中, 所有节点的配置信息是一致的,比如Kafka集群</li><li>对配置信息修改后, 希望能够快速同步到各个节点上</li></ol></li><li>配置管理可交由Zookeeper实现 <ol><li>可将配置信息写入Zookeeper上的一个Znode</li><li>各个客户端服务器监听这个Znode</li><li>一旦Znode中的数据发生修改,则会对Client发出通知</li></ol></li></ol><h4 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h4>',12)])])}const k=e(i,[["render",l]]);export{_ as __pageData,k as default};
